function validate([destination, k]) {
  if (destination.length !== 2) return 'destination holds exactly two numbers, [row, column].';
  const [row, column] = destination;
  if (row < 1 || row > 15 || column < 1 || column > 15) return 'row and column are between 1 and 15.';
  let count = 1;
  for (let i = 1; i <= row; i++) count = count * (column + i) / i;
  if (k < 1 || k > count) return `k must be between 1 and ${count}, the number of valid instruction strings.`;
  return null;
}

