function kthSmallestPath(destination, k) {
  const [row, column] = destination;
  const total = row + column;
  const choose = Array.from({ length: total + 1 }, () => new Array(total + 1).fill(0));
  for (let n = 0; n <= total; n++) {
    choose[n][0] = 1;
    for (let r = 1; r <= n; r++) {
      choose[n][r] = choose[n - 1][r - 1] + choose[n - 1][r];
    }
  }

  let horizontal = column;
  let vertical = row;
  let path = '';
  while (horizontal + vertical > 0) {
    const withH = choose[horizontal + vertical - 1][vertical];
    if (horizontal > 0 && k <= withH) {
      path += 'H';
      horizontal--;
    } else {
      k -= withH;
      path += 'V';
      vertical--;
    }
  }
  return path;
}

