function kthSmallestPath(destination, k) {
  // List the strings in order with a depth-first search that tries 'H' before 'V', stopping at the k-th.
  const [row, column] = destination;
  let seen = 0;
  let answer = null;
  const walk = (prefix, h, v) => {
    if (answer !== null) return;
    if (h === 0 && v === 0) {
      seen++;
      if (seen === k) answer = prefix;
      return;
    }
    if (h > 0) walk(prefix + 'H', h - 1, v);
    if (v > 0) walk(prefix + 'V', h, v - 1);
  };
  walk('', column, row);
  return answer;
}

