function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const row = large ? (rand() < 0.4 ? 15 : int(8, 15)) : int(1, 5);
  const column = large ? (rand() < 0.4 ? 15 : int(8, 15)) : int(1, 5);
  let count = 1;
  for (let i = 1; i <= row; i++) count = count * (column + i) / i;
  const roll = rand();
  const k = roll < 0.1 ? 1 : roll < 0.2 ? count : int(1, count);
  return [[row, column], k];
}
